# =========================
# AUDIT LOG SYSTEM
# =========================
# Persistent per-user audit trail. Records who did what and when.
# Stored as a single rolling JSON file per user. Capped at 1000 events.

_AUDIT_LOCK = threading.Lock()
_AUDIT_MAX  = 1000

def _audit_log(action: str, detail: dict = None, username: str = None) -> None:
    """Record an audit event. Safe to call from any route."""
    try:
        if not username:
            try:
                u = current_user()
                username = (u.get("username") if isinstance(u, dict) else None) or "system"
            except Exception:
                username = "system"
        record = {
            "ts":     now_iso(),
            "action": action,
            "user":   username,
            "ip":     (request.headers.get("X-Forwarded-For", request.remote_addr or "") if request else "").split(",")[0].strip(),
            "detail": detail or {}
        }
        audit_path = Path(DATA_DIR) / f"audit_{username}.json"
        with _AUDIT_LOCK:
            try:
                events = json.loads(audit_path.read_text(encoding="utf-8")) if audit_path.exists() else []
            except Exception:
                events = []
            events.append(record)
            if len(events) > _AUDIT_MAX:
                events = events[-_AUDIT_MAX:]
            tmp = str(audit_path) + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(events, f)
            os.replace(tmp, str(audit_path))
    except Exception:
        pass

# =========================
# STARTUP MIGRATION: Fix saved teammate job titles

def _stripe_ready() -> bool:
    # Ready if secret key + at least one plan price ID is configured
    return bool(STRIPE_SECRET_KEY and (
        STRIPE_PRICE_ID_FOUNDER or STRIPE_PRICE_ID_STARTER or
        STRIPE_PRICE_ID_GROWTH or STRIPE_PRICE_ID
    ))

def _stripe_api(method: str, path: str, data: Optional[Dict[str, Any]] = None) -> Tuple[int, Dict[str, Any]]:
    """Minimal Stripe REST wrapper — no stripe-python dep required."""
    _req = requests
    url = f"https://api.stripe.com/v1{path}"
    headers = {"Authorization": f"Bearer {STRIPE_SECRET_KEY}"}
    try:
        if method.upper() == "GET":
            r = _req.get(url, headers=headers, params=data or {}, timeout=20)
        else:
            r = _req.post(url, headers=headers, data=data or {}, timeout=20)
        return r.status_code, (r.json() if r.content else {})
    except Exception as e:
        return 0, {"error": {"message": str(e)}}

def _stripe_verify_webhook(payload: bytes, sig_header: str) -> Tuple[bool, Dict[str, Any]]:
    """Verify Stripe-Signature header and return (ok, event_dict)."""
    if not STRIPE_WEBHOOK_SECRET:
        # SECURITY: Never accept unverified webhook payloads.
        # Set STRIPE_WEBHOOK_SECRET in your environment to enable webhook processing.
        print("[SECURITY] Stripe webhook received but STRIPE_WEBHOOK_SECRET is not set — rejecting.", flush=True)
        return False, {}
    try:
        parts: Dict[str, str] = {}
        for chunk in sig_header.split(","):
            if "=" in chunk:
                k, v = chunk.split("=", 1)
                parts[k.strip()] = v.strip()
        ts   = parts.get("t", "")
        v1   = parts.get("v1", "")
        if not ts or not v1:
            return False, {}
        signed = ts.encode("utf-8") + b"." + payload
        expected = hmac.new(
            STRIPE_WEBHOOK_SECRET.encode("utf-8"), signed, hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(expected, v1):
            return False, {}
        # Replay attack protection: reject webhooks older than 5 minutes
        try:
            ts_age = abs(time.time() - int(ts))
            if ts_age > 300:
                print(f"[SECURITY] Stripe webhook rejected: timestamp too old ({ts_age:.0f}s)", flush=True)
                return False, {}
        except Exception:
            return False, {}
        return True, json.loads(payload.decode("utf-8"))
    except Exception:
        return False, {}

def _load_stripe_sessions() -> Dict[str, Any]:
    return load_json(STRIPE_SESSIONS_PATH, {})

def _save_stripe_sessions(data: Dict[str, Any]) -> None:
    save_json(STRIPE_SESSIONS_PATH, data)

def _generate_seat_for_stripe(email: str, customer_id: str, session_id: str, name: str = "", plan: str = "starter") -> str:
    """Create a fresh seat code tied to a completed Stripe checkout and return it."""
    # Idempotent: if we already made one for this session, return it
    sess_data = _load_stripe_sessions()
    if session_id in sess_data:
        return sess_data[session_id].get("code", "")

    data  = _load_seats()
    seats = data.get("seats") or {}
    nums  = [v.get("seat_num", 0) for v in seats.values()]
    next_num = (max(nums) if nums else 0) + 1
    code = f"SA-{secrets.token_urlsafe(8).upper()[:8]}"
    while code in seats:
        code = f"SA-{secrets.token_urlsafe(8).upper()[:8]}"

    plan_info = PLANS.get(plan) or PLANS.get("starter") or {}
    # Calculate trial end date
    _trial_end = None
    if FREE_TRIAL_DAYS > 0:
        _trial_end = (datetime.utcnow() + timedelta(days=FREE_TRIAL_DAYS)).isoformat() + "Z"

    seats[code] = {
        "seat_num":          next_num,
        "label":             name.strip() if name.strip() else f"Stripe Seat #{next_num}",
        "status":            "active",
        "claimed_by":        None,
        "created_at":        now_iso(),
        "claimed_at":        None,
        "notes":             f"stripe_customer={customer_id}",
        "stripe_customer_id": customer_id,
        "stripe_session_id":  session_id,
        "stripe_email":       email,
        "holder_name":        name.strip(),
        "holder_email":       email.strip(),
        "source":             "stripe",
        "plan":               plan,
        "plan_name":          plan_info.get("name", "Starter Operator"),
        "trial_days":         FREE_TRIAL_DAYS,
        "trial_end":          _trial_end,
        "trial_active":       (FREE_TRIAL_DAYS > 0),
    }
    data["seats"] = seats
    _save_seats(data)

    sess_data[session_id] = {"code": code, "email": email, "name": name, "plan": plan, "created_at": now_iso()}
    _save_stripe_sessions(sess_data)
    return code

def _stripe_session_code(stripe_session_id: str) -> Tuple[str, str]:
    """
    Given a Stripe checkout session_id, return (seat_code, email).
    Checks local cache first; falls back to Stripe API.
    Returns ("", "") on failure.
    """
    if not STRIPE_SECRET_KEY:
        return "", ""
    sess_data = _load_stripe_sessions()
    if stripe_session_id in sess_data:
        rec = sess_data[stripe_session_id]
        return rec.get("code", ""), rec.get("email", "")
    # Fetch from Stripe
    status, data = _stripe_api("GET", f"/checkout/sessions/{stripe_session_id}")
    if status != 200:
        return "", ""
    pstatus = data.get("payment_status", "")
    if pstatus not in ("paid", "no_payment_needed"):
        return "", ""
    customer_id = data.get("customer") or ""
    email = ((data.get("customer_details") or {}).get("email") or
             data.get("customer_email") or "")
    code = _generate_seat_for_stripe(email, customer_id, stripe_session_id)
    return code, email

def _load_or_create_secret() -> str:
    try:
        if SECRET_PATH.exists():
            s = SECRET_PATH.read_text(encoding="utf-8").strip()
            if s:
                return s
    except Exception:
        pass
    s = secrets.token_hex(32)
    try:
        SECRET_PATH.write_text(s, encoding="utf-8")
    except Exception:
        pass
    return s

app.secret_key = os.getenv("APP_SECRET", "") or _load_or_create_secret()
app.config["SESSION_COOKIE_HTTPONLY"] = True
app.config["SESSION_COOKIE_SAMESITE"] = "Lax"
# Set Secure cookie flag when running behind HTTPS (detected via PUBLIC_BASE_URL)
app.config["SESSION_COOKIE_SECURE"] = PUBLIC_BASE_URL.startswith("https://")
app.config["PERMANENT_SESSION_LIFETIME"] = timedelta(days=30)

# =========================
# LOGIN BRUTE-FORCE PROTECTION
# =========================
# In-memory store: { username_key -> {"count": int, "locked_until": iso_str|None} }
# Persisted to DATA/login_attempts.json so lockouts survive server restarts.
_LOGIN_ATTEMPTS: Dict[str, Any] = {}
_LOGIN_ATTEMPTS_LOCK = __import__("threading").Lock()
_MAX_LOGIN_ATTEMPTS = 5
_LOCKOUT_MINUTES    = 15

def _login_attempts_path() -> "Path":
    try:
        return DATA / "login_attempts.json"
    except Exception:
        return Path("login_attempts.json")

def _load_login_attempts() -> None:
    """Load persisted lockouts at startup (best-effort)."""
    try:
        p = _login_attempts_path()
        if p.exists():
            raw = json.loads(p.read_text(encoding="utf-8"))
            if isinstance(raw, dict):
                _LOGIN_ATTEMPTS.update(raw)
    except Exception:
        pass

def _persist_login_attempts() -> None:
    """Atomically write lockout state to disk. Must be called inside _LOGIN_ATTEMPTS_LOCK."""
    try:
        p = _login_attempts_path()
        tmp = p.with_suffix(".tmp")
        tmp.write_text(json.dumps(_LOGIN_ATTEMPTS), encoding="utf-8")
        tmp.replace(p)
    except Exception:
        pass

def _login_key(username: str) -> str:
    """Key by username so lockout is per-account, not per-IP (harder to spoof)."""
    return f"login:{username.lower().strip()}"

def _check_login_allowed(username: str) -> Tuple[bool, str]:
    """Returns (allowed, error_message)."""
    key = _login_key(username)
    with _LOGIN_ATTEMPTS_LOCK:
        rec = _LOGIN_ATTEMPTS.get(key)
        if not rec:
            return True, ""
        locked_until_str = rec.get("locked_until")
        if locked_until_str:
            try:
                locked_until = datetime.fromisoformat(str(locked_until_str).replace("Z", ""))
                if datetime.utcnow() < locked_until:
                    remaining = int((locked_until - datetime.utcnow()).total_seconds() / 60) + 1
                    return False, f"Too many failed attempts. Account locked for {remaining} more minute(s). Try again later."
            except Exception:
                pass
        return True, ""

def _record_login_failure(username: str) -> None:
    key = _login_key(username)
    with _LOGIN_ATTEMPTS_LOCK:
        rec = _LOGIN_ATTEMPTS.get(key) or {"count": 0, "locked_until": None}
        # Reset if previous lockout has expired
        locked_str = rec.get("locked_until")
        if locked_str:
            try:
                if datetime.utcnow() >= datetime.fromisoformat(str(locked_str).replace("Z", "")):
                    rec = {"count": 0, "locked_until": None}
            except Exception:
                rec = {"count": 0, "locked_until": None}
        rec["count"] = rec.get("count", 0) + 1
        if rec["count"] >= _MAX_LOGIN_ATTEMPTS:
            rec["locked_until"] = (datetime.utcnow() + timedelta(minutes=_LOCKOUT_MINUTES)).isoformat() + "Z"
        _LOGIN_ATTEMPTS[key] = rec
        _persist_login_attempts()

def _clear_login_failures(username: str) -> None:
    key = _login_key(username)
    with _LOGIN_ATTEMPTS_LOCK:
        _LOGIN_ATTEMPTS.pop(key, None)
        _persist_login_attempts()

# =========================
# API RATE LIMITING (per-user, in-memory)
# =========================
# Prevents runaway usage / API cost abuse. Limits: calls per minute per user.
# These are intentionally generous for normal use but catch bots/loops.
# Limits per 60-second window, by endpoint category
RATE_LIMIT_CHAT       = int(os.getenv("RATE_LIMIT_CHAT", "30"))
RATE_LIMIT_IMAGE      = int(os.getenv("RATE_LIMIT_IMAGE", "10"))
RATE_LIMIT_EMAIL      = int(os.getenv("RATE_LIMIT_EMAIL", "20"))
RATE_LIMIT_UPLOAD     = int(os.getenv("RATE_LIMIT_UPLOAD", "20"))
RATE_LIMIT_GENERAL    = int(os.getenv("RATE_LIMIT_GENERAL", "120"))
RATE_LIMIT_WINDOW_SEC = 60

# ── In-memory rate limiter with periodic disk flush ──────────────────────────
# Previously the rate limiter read AND wrote the JSON file on every single API
# request — a disk round-trip on every call. Now we keep state in memory and
# flush to disk in a background thread every 30 s.
# This keeps cross-restart persistence while eliminating per-request disk I/O.
_RATE_LIMITS_LOCK = threading.Lock()
_RL_MEM: Dict[str, Any] = {}   # key -> {"count": int, "window_start": float}
_RL_MEM_DIRTY = False           # True when in-memory state has unflushed changes

def _rl_file() -> str:
    return os.path.join(DATA_DIR, "_rate_limits.json")

def _rl_cleanup(data: dict, now_ts: float) -> dict:
    """Remove expired keys to keep the store compact."""
    cutoff = now_ts - RATE_LIMIT_WINDOW_SEC * 2
    return {k: v for k, v in data.items() if v.get("window_start", 0) > cutoff}

def _rl_load_from_disk() -> None:
    """Warm the in-memory store from disk at startup (best-effort)."""
    try:
        with open(_rl_file(), "r", encoding="utf-8") as f:
            raw = json.load(f)
        if isinstance(raw, dict):
            with _RATE_LIMITS_LOCK:
                _RL_MEM.update(raw)
    except Exception:
        pass

def _rl_flush_to_disk() -> None:
    """Write the in-memory rate limit state to disk. Called by the background flusher."""
    global _RL_MEM_DIRTY
    with _RATE_LIMITS_LOCK:
        if not _RL_MEM_DIRTY:
            return
        now_ts = datetime.utcnow().timestamp()
        cleaned = _rl_cleanup(dict(_RL_MEM), now_ts)
        _RL_MEM.clear()
        _RL_MEM.update(cleaned)
        _RL_MEM_DIRTY = False
        snapshot = dict(_RL_MEM)
    try:
        tmp = _rl_file() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(snapshot, f)
        os.replace(tmp, _rl_file())
    except Exception:
        pass

def _rl_background_flusher() -> None:
    """Daemon thread: persist rate limit state to disk every 30 seconds."""
    while True:
        time.sleep(30)
        try:
            _rl_flush_to_disk()
        except Exception:
            pass

# Warm from disk then start the flusher
_rl_load_from_disk()
threading.Thread(target=_rl_background_flusher, daemon=True, name="rl-flusher").start()

def _rate_limit_check(key: str, limit: int) -> Tuple[bool, str]:
    """Returns (allowed, error_message). Pure in-memory — no disk I/O per call."""
    global _RL_MEM_DIRTY
    now_ts = datetime.utcnow().timestamp()
    with _RATE_LIMITS_LOCK:
        rec = _RL_MEM.get(key)
        if rec is None or (now_ts - rec.get("window_start", 0)) > RATE_LIMIT_WINDOW_SEC:
            _RL_MEM[key] = {"count": 1, "window_start": now_ts}
            _RL_MEM_DIRTY = True
            return True, ""
        if rec["count"] >= limit:
            wait = int(RATE_LIMIT_WINDOW_SEC - (now_ts - rec["window_start"])) + 1
            return False, f"Rate limit reached. Please wait {wait} second(s) before trying again."
        rec["count"] += 1
        _RL_MEM_DIRTY = True
        return True, ""

def _get_rate_key(category: str) -> str:
    """Build a per-user rate limit key. Falls back to IP if not logged in."""
    try:
        u = current_user()
        uname = (u.get("username") if isinstance(u, dict) else None) or ""
        if uname:
            return f"rl:{category}:{uname}"
    except Exception:
        pass
    ip = (request.headers.get("X-Forwarded-For") or request.remote_addr or "unknown").split(",")[0].strip()
    return f"rl:{category}:ip:{ip}"

def _check_rate_limit(category: str, limit: int):
    """Call from route handlers. Returns a 429 response or None if allowed."""
    key = _get_rate_key(category)
    allowed, msg = _rate_limit_check(key, limit)
    if not allowed:
        return jsonify({"ok": False, "error": msg}), 429
    return None


def load_users() -> Dict[str, Any]:
    data = load_json(USERS_PATH, {"users": {}, "updated_at": None})
    if not isinstance(data, dict):
        data = {"users": {}, "updated_at": None}
    data.setdefault("users", {})
    return data

def save_users(data: Dict[str, Any]) -> None:
    global _HAS_ANY_USER_CACHE
    data["updated_at"] = now_iso()
    save_json(USERS_PATH, data)
    # Prime the cache — if we just saved at least one user, latch it to True
    if data.get("users"):
        with _HAS_ANY_USER_LOCK:
            _HAS_ANY_USER_CACHE = True

_HAS_ANY_USER_CACHE: Optional[bool] = None  # None = unchecked, True/False = known
_HAS_ANY_USER_LOCK = threading.Lock()

def has_any_user() -> bool:
    """Return True if at least one user account exists.
    Once True, the result is cached for the lifetime of the process — users can
    only be added, never removed, so this is safe. The setup page is only shown
    when False, i.e., before the very first account is created.
    """
    global _HAS_ANY_USER_CACHE
    with _HAS_ANY_USER_LOCK:
        if _HAS_ANY_USER_CACHE is True:
            return True
        result = bool((load_users().get("users") or {}))
        if result:
            _HAS_ANY_USER_CACHE = True  # latch permanently once True
        return result

def _clean_username(u: str) -> str:
    u = (u or "").strip().lower()
    u = re.sub(r"[^a-z0-9_\.\-]+", "", u)
    u = u.strip(".-_")   # No leading/trailing dots, dashes, underscores
    u = u[:40]  # Hard cap — prevents absurdly long usernames
    return u

def _find_user_by_login(identifier: str) -> Optional[Dict[str, Any]]:
    """Look up a user by username. The email field is no longer used for registration,
    but this stays in case old accounts have emails stored."""
    identifier = (identifier or "").strip().lower()
    if not identifier:
        return None
    data = load_users()
    users = data.get("users") or {}
    # Direct username match first
    clean = re.sub(r"[^a-z0-9_\.\-]+", "", identifier)
    if clean in users:
        return users[clean]
    return None


def _validate_password_strength(password: str) -> Tuple[bool, str]:
    """Returns (ok, error_message). Enforces minimum password requirements."""
    if not password or len(password) < 8:
        return False, "Password must be at least 8 characters."
    if not any(c.isdigit() or not c.isalpha() for c in password):
        return False, "Password must contain at least one number or special character."
    return True, ""

def _new_user(username: str, password: str, email: str = "", is_admin: bool = False) -> Dict[str, Any]:
    return {
        "username": username,
        "password_hash": generate_password_hash(password),
        "email": (email or "").strip(),
        "is_admin": is_admin,
        "created_at": now_iso(),
        "updated_at": now_iso(),
        "tos_accepted_at": now_iso(),
        "settings": {
            "openai_key": "",
            "tooltip_level": "medium",  # new users get tips by default
            "smtp": {
                "host": "",
                "port": 587,
                "user": "",
                "pass": "",
                "from_name": ""
            }
        },
        "reset": {"token_hash": "", "created_at": None}
    }

_CU_UNSET = object()  # module-level sentinel — distinct from None (logged-out user)

def current_user() -> Optional[Dict[str, Any]]:
    """Return the current authenticated user dict, or None.
    Result is cached on Flask's g object so users.json is read at most once
    per request — previously it was read on every single call.
    g is always request-scoped, so the cache is never stale across requests.
    Background threads have no g context; the try/except handles that safely.
    """
    try:
        cached = getattr(g, "_current_user", _CU_UNSET)
        if cached is not _CU_UNSET:
            return cached  # type: ignore[return-value]
    except RuntimeError:
        # No application/request context (e.g. background thread) — skip cache.
        pass

    # Admin impersonation: if active, return the impersonated user's record
    impersonating = session.get("_impersonating_as")
    if impersonating:
        data = load_users()
        result = (data.get("users") or {}).get(impersonating)
        try:
            g._current_user = result
        except RuntimeError:
            pass
        return result

    uname = session.get("user")
    # Historically we stored the username string in session["user"].
    # Some earlier builds accidentally stored a dict here; support both.
    if isinstance(uname, dict):
        uname = uname.get("username")
    if not uname:
        try:
            g._current_user = None
        except RuntimeError:
            pass
        return None

    data = load_users()
    result = (data.get("users") or {}).get(uname)
    try:
        g._current_user = result
    except RuntimeError:
        pass
    return result

def ensure_local_owner_user() -> str:
    """Ensure a local owner user exists for first-run / setup-less deployments.

    Returns the username to place in session["user"].
    """
    data = load_users()
    users = data.get("users") or {}
    if "local" not in users:
        # Create a deterministic local owner user.
        # Password is irrelevant for this bootstrap flow; the UI can still
        # support full login/reset if you later enable it.
        users["local"] = _new_user("local", password=str(uuid.uuid4()), email="")
        data["users"] = users
        save_users(data)
    return "local"

def login_required_api() -> bool:
    p = request.path or ""
    if p.startswith("/api/") and p not in ("/api/login", "/api/logout", "/api/reset_request", "/api/reset_password", "/api/me"):
        return True
    return False


