@app.get("/sitemap.xml")
def sitemap_xml():
    """XML sitemap for marketing pages."""
    base = (PUBLIC_BASE_URL or "").rstrip("/")
    from datetime import date
    today = date.today().isoformat()
    urls = [
        ("",          "1.0",  "daily"),
        ("/pricing",  "0.9",  "weekly"),
        ("/showcase", "0.8",  "weekly"),
        ("/terms",    "0.5",  "monthly"),
        ("/privacy",  "0.5",  "monthly"),
        ("/login",    "0.6",  "monthly"),
        ("/register", "0.7",  "monthly"),
    ]
    xml = '<?xml version="1.0" encoding="UTF-8"?>\n'
    xml += '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
    for path, priority, freq in urls:
        xml += f"""  <url>
    <loc>{base}{path}</loc>
    <lastmod>{today}</lastmod>
    <changefreq>{freq}</changefreq>
    <priority>{priority}</priority>
  </url>\n"""
    xml += "</urlset>"
    return xml, 200, {"Content-Type": "application/xml; charset=utf-8"}


# ── PWA icons ──────────────────────────────────────────────────────────────────
# Generated at runtime so no static files are needed on Render.
def _pwa_icon_png(size: int) -> bytes:
    """Return a minimal branded PNG icon (dark bg + purple circle) for any size."""
    W = H = size
    bg = (9, 13, 25)       # #090d19
    ac = (109, 40, 217)    # #6d28d9 purple
    hi = (167, 139, 250)   # #a78bfa light purple
    cx = cy = W / 2.0
    r_outer_sq = (W * 0.42) ** 2
    r_inner_sq = (W * 0.20) ** 2
    rows = bytearray()
    for y in range(H):
        rows.append(0)  # PNG filter None
        for x in range(W):
            d2 = (x - cx) ** 2 + (y - cy) ** 2
            if d2 <= r_inner_sq:
                rows.extend(hi)
            elif d2 <= r_outer_sq:
                rows.extend(ac)
            else:
                rows.extend(bg)
    def _chunk(tag: bytes, data: bytes) -> bytes:
        crc = zlib.crc32(tag + data) & 0xffffffff
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", crc)
    ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)  # 8-bit RGB
    idat = zlib.compress(bytes(rows), 6)
    return b"\x89PNG\r\n\x1a\n" + _chunk(b"IHDR", ihdr) + _chunk(b"IDAT", idat) + _chunk(b"IEND", b"")

# Cache icons at module level so they're only generated once per process
_PWA_ICON_180 = _pwa_icon_png(180)
_PWA_ICON_192 = _pwa_icon_png(192)
_PWA_ICON_512 = _pwa_icon_png(512)

