# =========================
# AUTOMATED DATA BACKUPS
# =========================
# Backs up the entire DATA directory to a local /var/backups folder every
# BACKUP_INTERVAL_HOURS hours (default 6). Each backup is a timestamped .tar.gz.
# Keeps the last BACKUP_KEEP copies and deletes older ones automatically.
#
# For off-site backups, set BACKUP_S3_BUCKET + AWS_ACCESS_KEY_ID + AWS_SECRET_ACCESS_KEY
# and each local backup will also be pushed to S3/Backblaze B2.
#
BACKUP_INTERVAL_HOURS = int(os.getenv("BACKUP_INTERVAL_HOURS", "6"))
BACKUP_KEEP           = int(os.getenv("BACKUP_KEEP", "24"))       # 24 × 6h = 6 days of local history
BACKUP_S3_BUCKET      = os.getenv("BACKUP_S3_BUCKET", "").strip() # e.g. my-app-backups
BACKUP_DIR            = Path(os.getenv("BACKUP_DIR", "/var/backups/simply_agentic"))

def _run_backup() -> None:
    """Create a timestamped .tar.gz of DATA, prune old copies, optionally push to S3."""
    import tarfile
    try:
        BACKUP_DIR.mkdir(parents=True, exist_ok=True)
        stamp = datetime.utcnow().strftime("%Y%m%d_%H%M%S")
        dest  = BACKUP_DIR / f"data_{stamp}.tar.gz"
        with tarfile.open(dest, "w:gz") as tar:
            tar.add(str(DATA), arcname="data")
        print(f"[BACKUP] Created {dest} ({dest.stat().st_size // 1024} KB)", flush=True)

        # Prune oldest backups beyond BACKUP_KEEP
        backups = sorted(BACKUP_DIR.glob("data_*.tar.gz"), key=lambda p: p.name)
        for old in backups[:-BACKUP_KEEP]:
            try:
                old.unlink()
                print(f"[BACKUP] Pruned old backup: {old.name}", flush=True)
            except Exception:
                pass

        # Optional S3/B2 push — requires boto3 and credentials in env
        if BACKUP_S3_BUCKET:
            try:
                import boto3  # type: ignore
                s3 = boto3.client("s3")
                s3_key = f"backups/{dest.name}"
                s3.upload_file(str(dest), BACKUP_S3_BUCKET, s3_key)
                print(f"[BACKUP] Uploaded to s3://{BACKUP_S3_BUCKET}/{s3_key}", flush=True)
            except Exception as e:
                print(f"[BACKUP] S3 upload failed: {e}", flush=True)
    except Exception as e:
        print(f"[BACKUP] Backup failed: {e}", flush=True)

def _backup_loop() -> None:
    """Background thread: run a backup every BACKUP_INTERVAL_HOURS hours."""
    import time
    # Stagger first run by 5 min so it doesn't fire during a cold-start spike
    time.sleep(300)
    while True:
        _run_backup()
        time.sleep(BACKUP_INTERVAL_HOURS * 3600)

def _start_backup_thread() -> None:
    if BACKUP_INTERVAL_HOURS <= 0:
        print("[BACKUP] Automated backups disabled (BACKUP_INTERVAL_HOURS=0).", flush=True)
        return
    t = threading.Thread(target=_backup_loop, daemon=True, name="backup-loop")
    t.start()
    print(f"[BACKUP] Backup thread started — every {BACKUP_INTERVAL_HOURS}h → {BACKUP_DIR}", flush=True)

try:
    _start_backup_thread()
except Exception as _be:
    print(f"[BACKUP] Could not start backup thread: {_be}", flush=True)



TASK_LOG_DIR = DATA / "task_logs"

def _safe_name(s: str) -> str:
    return re.sub(r"[^a-zA-Z0-9_-]+", "_", (s or "anon"))[:80] or "anon"

# ---------------- Client Memory Profiles (additive) ----------------
def _clients_path_for_user(username: str) -> str:
    base = os.path.join(DATA_DIR, "clients")
    os.makedirs(base, exist_ok=True)
    safe = re.sub(r"[^a-zA-Z0-9_.-]+", "_", username or "anon")
    return os.path.join(base, f"{safe}.json")

def _load_clients(username: str) -> Dict[str, Any]:
    path = _clients_path_for_user(username)
    if not os.path.exists(path):
        return {"active_client_id": "", "clients": {}}
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            return {"active_client_id": "", "clients": {}}
        data.setdefault("active_client_id", "")
        data.setdefault("clients", {})
        if not isinstance(data["clients"], dict):
            data["clients"] = {}
        return data
    except Exception:
        return {"active_client_id": "", "clients": {}}

def _save_clients(username: str, data: Dict[str, Any]) -> None:
    path = _clients_path_for_user(username)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    os.replace(tmp, path)

def _get_active_client(username: str) -> Dict[str, Any]:
    data = _load_clients(username)
    cid = (data.get("active_client_id") or "").strip()
    clients = data.get("clients") or {}
    if cid and cid in clients and isinstance(clients[cid], dict):
        c = clients[cid]
        c.setdefault("id", cid)
        return c
    return {}

def _get_session_username() -> str:
    # Admin impersonation takes priority
    impersonating = session.get("_impersonating_as")
    if impersonating:
        return str(impersonating)
    u = session.get("user")
    return (u.get("username") if isinstance(u, dict) else None) or (u if isinstance(u, str) else None) or "anon"

def _new_client_id() -> str:
    return "c_" + uuid.uuid4().hex[:10]

def _task_log_path_for_user(username: Optional[str]) -> Path:
    TASK_LOG_DIR.mkdir(parents=True, exist_ok=True)
    return TASK_LOG_DIR / f"{_safe_name(username or 'anon')}.jsonl"

def _prune_task_log(path: Path, keep: int = 4000, cap: int = 5000) -> None:
    """[UPGRADE 2] If the JSONL log exceeds `cap` lines, trim to the most recent `keep` lines.
    Uses an atomic rename so a mid-write crash never corrupts the file."""
    try:
        if not path.exists() or path.stat().st_size < 512 * 1024:
            return  # skip if under 512 KB — no need to prune yet
        lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
        if len(lines) <= cap:
            return
        trimmed = "\n".join(lines[-keep:]) + "\n"
        tmp = path.with_suffix(".tmp")
        tmp.write_text(trimmed, encoding="utf-8")
        tmp.replace(path)
    except Exception:
        pass

def append_task_log(action: str, record: Dict[str, Any], teammate: str = "", status: str = "success") -> None:
    """Append-only task log. One JSON object per line (JSONL)."""
    try:
        u = session.get("user")
        username = (u.get("username") if isinstance(u, dict) else None) or (u if isinstance(u, str) else None) or "anon"
        path = _task_log_path_for_user(username)
        entry = {
            "id": str(uuid.uuid4()),
            "ts": now_iso(),
            "user": username,
            "teammate": teammate or record.get("name") or record.get("from_teammate") or "",
            "action": action,
            "status": status,
            "record": record,
        }
        with path.open("a", encoding="utf-8") as f:
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")
        _prune_task_log(path)  # [UPGRADE 2] auto-prune if file has grown too large
    except Exception:
        # Task logging must never break core flows
        pass

def read_task_log(limit: int = 200, teammate: str = "", status: str = "") -> List[Dict[str, Any]]:
    username = session.get("user") or "anon"
    path = _task_log_path_for_user(username)
    if not path.exists():
        return []
    try:
        lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
        # take the most recent N lines (small, safe default)
        lines = lines[-max(1, min(2000, limit * 3)):]
        out: List[Dict[str, Any]] = []
        for line in reversed(lines):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception:
                continue
            if teammate and (obj.get("teammate") or "") != teammate:
                continue
            if status and (obj.get("status") or "") != status:
                continue
            out.append(obj)
            if len(out) >= limit:
                break
        return list(reversed(out))
    except Exception:
        return []


