def _calendar_create_event(access_token: str, title: str, start_iso: str, end_iso: str, timezone: str, attendees: Optional[List[str]] = None, description: str = "", location: str = "", use_meet: bool = False) -> Dict[str, Any]:
    _uuid = uuid
    url = "https://www.googleapis.com/calendar/v3/calendars/primary/events"
    event: Dict[str, Any] = {
        "summary": title,
        "description": description or "",
        "location": location or "",
        "start": {"dateTime": start_iso, "timeZone": timezone},
        "end": {"dateTime": end_iso, "timeZone": timezone},
    }
    if attendees:
        clean = [{"email": a.strip()} for a in attendees if (a or "").strip()]
        if clean:
            event["attendees"] = clean
            event["sendUpdates"] = "all"
    if use_meet:
        event["conferenceData"] = {
            "createRequest": {
                "requestId": str(_uuid.uuid4()),
                "conferenceSolutionKey": {"type": "hangoutsMeet"}
            }
        }
    params = {"conferenceDataVersion": "1"} if use_meet else {}
    r = requests.post(url, headers={"Authorization": f"Bearer {access_token}", "Content-Type": "application/json"}, json=event, params=params, timeout=20)
    data = r.json() if r.content else {}
    if r.status_code >= 400:
        raise Exception(f"Calendar API error: {data}")
    return data

def _calendar_move_event(access_token: str, event_id: str, new_start_iso: str, new_end_iso: str, timezone: str, send_updates: str = "none") -> Dict[str, Any]:
    """PATCH an existing Google Calendar event to a new time — does NOT create a duplicate."""
    url = f"https://www.googleapis.com/calendar/v3/calendars/primary/events/{event_id}"
    body = {
        "start": {"dateTime": new_start_iso, "timeZone": timezone},
        "end":   {"dateTime": new_end_iso,   "timeZone": timezone},
    }
    params = {"sendUpdates": send_updates}
    r = requests.patch(url, headers={"Authorization": f"Bearer {access_token}", "Content-Type": "application/json"},
                       json=body, params=params, timeout=20)
    data = r.json() if r.content else {}
    if r.status_code >= 400:
        raise Exception(f"Calendar PATCH error: {data}")
    return data


def _calendar_check_conflicts(access_token: str, start_iso: str, end_iso: str, timezone: str = "UTC") -> List[Dict[str, Any]]:
    """Return list of busy time blocks overlapping [start_iso, end_iso]. Empty = no conflict."""
    try:
        url = "https://www.googleapis.com/calendar/v3/freeBusy"
        body = {"timeMin": start_iso, "timeMax": end_iso, "timeZone": timezone, "items": [{"id": "primary"}]}
        r = _retry_request("POST", url, headers={"Authorization": f"Bearer {access_token}", "Content-Type": "application/json"}, json=body, timeout=15)
        if r.status_code >= 400:
            return []
        return ((r.json() if r.content else {}).get("calendars") or {}).get("primary", {}).get("busy") or []
    except Exception:
        return []


def _strip_motion_boilerplate(text: str) -> str:
    """Strip Motion/third-party auto-generated boilerplate from event/task descriptions."""
    if not text:
        return ""
    import html as _html
    # Decode HTML entities and strip tags
    txt = re.sub(r"<[^>]*>", " ", text)
    txt = _html.unescape(txt).strip()
    # Remove Motion patterns
    patterns = [
        r"This event was created by Motion[\s\S]*",
        r"This task was created by Motion[\s\S]*",
        r"Created (in|by|via) Motion[\s\S]*",
        r"If you are a teammate of this person[\s\S]*",
        r"If you are the owner of this event[\s\S]*",
        r"feel free to book over this event[\s\S]*",
        r"please view details of this task within Motion[\s\S]*",
        r"the task details are hidden for privacy[\s\S]*",
        r"Managed by Motion[\s\S]*",
        r"Scheduled by Motion[\s\S]*",
        r"To edit settings[\s\S]*",
        r"To disconnect Motion[\s\S]*",
        r"https?://app\.usemotion\.com\S*",
        r"https?://www\.usemotion\.com\S*",
    ]
    for pat in patterns:
        txt = re.sub(pat, "", txt, flags=re.IGNORECASE | re.DOTALL)
    txt = re.sub(r"\n{3,}", "\n\n", txt).strip()
    return txt


def _calendar_list_events(access_token: str, time_min: str, time_max: str, timezone: str, max_results: int = 250) -> List[Dict[str, Any]]:
    """Fetch events from ALL user calendars: primary + Google Tasks + every selected calendar.

    Previously only fetched 'primary', which missed Motion's calendar,
    work calendars, Google Tasks, and any other secondary calendars.
    Now fetches everything the user has access to.
    """
    _req = requests
    headers = {"Authorization": f"Bearer {access_token}"}
    base_params = {
        "timeMin": time_min, "timeMax": time_max,
        "singleEvents": "true", "orderBy": "startTime",
        "maxResults": str(max_results), "timeZone": timezone,
    }

    def _fetch_cal(cal_id: str) -> list:
        safe = _req.utils.quote(cal_id, safe="")
        try:
            r = _retry_request(
                "GET",
                f"https://www.googleapis.com/calendar/v3/calendars/{safe}/events",
                headers=headers, params=base_params, timeout=20)
            if r.status_code >= 400:
                return []
            return (r.json() if r.content else {}).get("items") or []
        except Exception as e:
            _capture_error(e, context="calendar_secondary_fetch")
            return []

    def _parse_items(items: list) -> List[Dict[str, Any]]:
        out = []
        for it in items:
            start = (it.get("start") or {}).get("dateTime") or (it.get("start") or {}).get("date") or ""
            end   = (it.get("end")   or {}).get("dateTime") or (it.get("end")   or {}).get("date") or ""
            raw_attendees = it.get("attendees") or []
            attendee_emails = [a.get("email", "") for a in raw_attendees
                               if a.get("email") and a.get("self") is not True]
            raw_desc = it.get("description", "") or ""
            is_motion_task = bool(re.search(
                r"(this task was created by motion|task was (created|scheduled|managed) by motion)",
                raw_desc, re.IGNORECASE))
            out.append({
                "id":               it.get("id", ""),
                "summary":          it.get("summary", ""),
                "start":            start,
                "end":              end,
                "htmlLink":         it.get("htmlLink", ""),
                "hangoutLink":      it.get("hangoutLink", ""),
                "recurringEventId": it.get("recurringEventId", ""),
                "description":      _strip_motion_boilerplate(raw_desc),
                "location":         it.get("location", ""),
                "attendees":        attendee_emails,
                "is_motion_task":   is_motion_task,
            })
        return out

    # ── 1. Primary calendar (always first) ──────────────────────────────────
    out  = _parse_items(_fetch_cal("primary"))
    seen = {e["id"] for e in out if e["id"]}

    # ── 2. Google Tasks calendar ─────────────────────────────────────────────
    #    Tasks created in Google Tasks / the Calendar task sidebar live here.
    for ev in _parse_items(_fetch_cal("tasks@group.v.calendar.google.com")):
        if ev["id"] not in seen:
            seen.add(ev["id"])
            out.append(ev)

    # ── 3. All other selected calendars ─────────────────────────────────────
    #    Includes Motion's calendar, work/school calendars, shared calendars.
    #    Requires calendar.readonly scope — silently skipped if token predates
    #    the scope upgrade (user will see the reconnect prompt in the calendar UI).
    try:
        cl_r = _req.get(
            "https://www.googleapis.com/calendar/v3/users/me/calendarList",
            headers=headers,
            params={"fields": "items(id,summary,selected,accessRole,primary)"},
            timeout=15)
        if cl_r.status_code == 200:
            items = (cl_r.json() if cl_r.content else {}).get("items") or []
            for cal_meta in items:
                cal_id = cal_meta.get("id") or ""
                if not cal_id:
                    continue
                # Skip ones we already fetched
                if cal_id in ("primary", "tasks@group.v.calendar.google.com"):
                    continue
                # Skip primary calendar by another name
                if cal_meta.get("primary"):
                    continue
                # Skip calendars the user has hidden in GCal
                if not cal_meta.get("selected", True):
                    continue
                for ev in _parse_items(_fetch_cal(cal_id)):
                    if ev["id"] not in seen:
                        seen.add(ev["id"])
                        out.append(ev)
    except Exception:
        pass  # Silently skip — old token without calendar.readonly scope

    return out


