@app.post("/api/calendar/event_meta")
def api_gcal_event_meta_set():
    """Save on_complete metadata for a Google Calendar event by event_id."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"
    payload = request.get_json(silent=True) or {}
    event_id = (payload.get("event_id") or "").strip()
    if not event_id:
        return jsonify({"ok": False, "error": "Missing event_id"}), 400
    meta = _load_gcal_event_meta(uname)
    _rd = payload.get("recur_days") or []
    _rdv = [int(d) for d in _rd if str(d).isdigit() or isinstance(d, int)] if isinstance(_rd, list) else (meta.get(event_id, {}).get("recur_days") or [])
    meta[event_id] = {
        "on_complete_teammate":    (payload.get("on_complete_teammate") or "").strip(),
        "on_complete_client_name": (payload.get("on_complete_client_name") or "").strip(),
        "on_complete_client_email":(payload.get("on_complete_client_email") or "").strip(),
        "done": bool(payload.get("done", meta.get(event_id, {}).get("done", False))),
        "gcal_item_type": (payload.get("gcal_item_type") or meta.get(event_id, {}).get("gcal_item_type") or "").strip(),
        "priority": (payload.get("priority") or meta.get(event_id, {}).get("priority") or "").strip(),
        "notes":    (payload.get("notes")    if payload.get("notes") is not None else meta.get(event_id, {}).get("notes") or ""),
        "title":    (payload.get("title")    if payload.get("title")    else meta.get(event_id, {}).get("title") or ""),
        "recurring": (payload.get("recurring") if payload.get("recurring") is not None else meta.get(event_id, {}).get("recurring") or "none"),
        "recur_days": _rdv,
        "updated_at": now_iso(),
    }
    _save_gcal_event_meta(uname, meta)
    # If on_complete fields are set and event is marked done, fire the completion action
    m = meta[event_id]
    if m.get("done") and m.get("on_complete_teammate") and m.get("on_complete_client_email"):
        # Build a synthetic task-like dict so we can reuse the task complete action API
        append_log("gcal_event_complete_action_queued", {
            "user": uname, "event_id": event_id,
            "teammate": m["on_complete_teammate"],
            "client": m["on_complete_client_email"],
        })
    return jsonify({"ok": True, "meta": m})


@app.post("/api/calendar/event_type_toggle")
def api_gcal_event_type_toggle():
    """Toggle a Google Calendar event between 'event' and 'task' display type."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"
    payload = request.get_json(silent=True) or {}
    event_id = (payload.get("event_id") or "").strip()
    new_type  = (payload.get("gcal_item_type") or "").strip()  # "event" or "task"
    if not event_id or new_type not in ("event", "task"):
        return jsonify({"ok": False, "error": "Missing event_id or invalid type"}), 400
    meta = _load_gcal_event_meta(uname)
