@app.post("/api/crm/clients/<client_id>/draft_outreach")
def api_crm_draft_outreach(client_id: str):
    """
    One-click AI outreach draft for a pipeline client.
    Calls Sunshine with full client context + operator profile.
    Returns email_draft {subject, body, to} for the email console.
    """
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"

    payload = request.get_json(silent=True) or {}
    channel = (payload.get("channel") or "email").strip().lower()

    crm    = _crm_load(uname)
    client = (crm.get("clients") or {}).get(client_id)
    if not client:
        return jsonify({"ok": False, "error": "Client not found"}), 404

    op       = _load_operator_profile(uname)
    op_name  = (op.get("display_name") or "Operator").strip()
    business = (op.get("business")     or "").strip()
    offers   = (op.get("offers")       or "").strip()

    name    = (client.get("name")           or "").strip()
    email   = (client.get("email")          or "").strip()
    phone   = (client.get("phone")          or "").strip()
    stage   = (client.get("pipeline_stage") or "Lead").strip()
    notes   = (client.get("notes")          or "").strip()
    company = (client.get("company")        or "").strip()
    tags    = ", ".join(client.get("tags") or [])
    first   = name.split()[0] if name else "there"
    last_contact   = (client.get("last_contact")   or "").strip()
    next_followup  = (client.get("next_followup")  or "").strip()
    today_str      = datetime.utcnow().strftime("%Y-%m-%d")

    context_lines = [
        f"Client name: {name}"                                         if name         else None,
        f"Company: {company}"                                          if company      else None,
        f"Pipeline stage: {stage}",
        f"Tags: {tags}"                                                if tags         else None,
        f"Last contacted: {last_contact}"                              if last_contact else "Last contacted: unknown",
        f"Notes about this client: {notes}"                            if notes        else None,
        f"Operator: {op_name}" + (f" at {business}" if business else ""),
        f"Our offer / service: {offers}"                               if offers       else None,
    ]
    context = "\n".join(l for l in context_lines if l)

    prompt = (
        f"Draft a warm, professional, concise outreach email for the following client. "
        f"Match the tone and next step appropriate for their pipeline stage: \'{stage}\'. "
        f"Lead with value — do NOT be pushy. Keep the body to 3-5 sentences max. "
        f"Sign off as {op_name}{(' at ' + business) if business else ''}. "
        f"Address the client as {first}.\n\n"
        f"Client context:\n{context}\n\n"
        f"Respond using EXACTLY this format and nothing else:\n"
        f"```email\n"
        f"to: {email}\n"
        f"subject: <write subject here>\n"
        f"body: <write email body here>\n"
        f"```"
    )

    reg       = load_registry(_get_session_username())
    installed = reg.get("installed") or {}
    teammate  = "Sunshine" if "Sunshine" in installed else (list(installed.keys())[0] if installed else None)
    if not teammate:
        return jsonify({"ok": False, "error": "No teammates installed"}), 400

    try:
        msg2, _, vision_images = build_prompt_with_attachments(prompt, [])
        user_content = _build_user_content(msg2, vision_images)
        defn       = installed[teammate]
        sys_prompt = teammate_system_prompt(defn)
        oai        = get_openai_client()
        resp = oai.chat.completions.create(
            model=(defn.get("preferred_model") or "").strip() or MODEL,
            messages=[
                {"role": "system", "content": sys_prompt},
                {"role": "user",   "content": user_content},
            ],
            temperature=0.65,
            timeout=60,
        )
        raw = (resp.choices[0].message.content or "").strip()
    except Exception as e:
        _, msg = _classify_openai_error(e)
        return jsonify({"ok": False, "error": msg}), 500

    # Auto-set last_contact = today so the CRM stays current
    try:
        crm2 = _crm_load(uname)
        if client_id in (crm2.get("clients") or {}):
            crm2["clients"][client_id]["last_contact"] = today_str
            _crm_save(uname, crm2)
    except Exception:
        pass

    draft = extract_email_draft(raw)
    if not draft:
        draft = {"to": email, "subject": f"Following up — {name}", "body": raw}
    if not draft.get("to") or not EMAIL_RE.match(str(draft.get("to") or "")):
        draft["to"] = email

    return jsonify({
        "ok":          True,
        "channel":     "email",
        "email_draft": draft,
        "teammate":    teammate,
        "client_name": name,
    })


@app.post("/api/crm/broadcast/email")
def api_crm_broadcast_email():
    """
    Bulk email sender for CRM.
    Supports:
      - payload.filter = {tag, stage, status, ids}
      - OR UI-friendly keys: all/tag/stage/status/client_ids
      - payload.dry_run = true (no sends, returns count only)
    Returns: {ok, count, sent, failed, results}
    """
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"

    payload = request.get_json(silent=True) or {}
    subject = (payload.get("subject") or "").strip()
    body_t = (payload.get("body") or "").strip()
    dry_run = bool(payload.get("dry_run"))
    if not subject or not body_t:
        return jsonify({"ok": False, "error": "Missing subject or body"}), 400

    # Accept either {filter:{...}} or direct UI keys.
    filt = payload.get("filter") or {}
    if not isinstance(filt, dict):
        filt = {}

    # UI keys override / fill filter when present.
    if payload.get("tag"):
        filt["tag"] = str(payload.get("tag") or "").strip()
    if payload.get("stage"):
        filt["stage"] = str(payload.get("stage") or "").strip()
    if payload.get("status"):
        filt["status"] = str(payload.get("status") or "").strip()
    if payload.get("client_ids"):
        ids = payload.get("client_ids") or []
        if isinstance(ids, str):
            ids = [x.strip() for x in ids.split(",") if x.strip()]
        if isinstance(ids, list):
            filt["ids"] = [str(x).strip() for x in ids if str(x).strip()]

    try:
        crm = _crm_load(uname)
        clients = list((crm.get("clients") or {}).values())
        # Filter matching contacts — exclude unsubscribed ones
        recipients = [
            c for c in clients
            if _crm_client_matches_filter(c, filt)
            and not c.get("email_unsubscribed")
        ]

        # Plan-based broadcast recipient limit
        plan_key  = _get_user_plan(uname)
        plan_info = PLANS.get(plan_key) or PLANS["starter"]
        max_recipients = plan_info.get("broadcast_recipients")  # None = unlimited
        if max_recipients is not None and len(recipients) > max_recipients:
            plan_name   = plan_info.get("name", "your plan")
            upgrade_to  = "Growth System ($97/mo)" if plan_key == "starter" else "Operator Pro ($197/mo)"
            return jsonify({"ok": False, "error": f"This broadcast would reach {len(recipients)} recipients — your {plan_name} limit is {max_recipients}. Narrow your filter or upgrade to {upgrade_to}."}), 403

        if dry_run:
            return jsonify({"ok": True, "count": len(recipients), "sent": 0, "failed": 0, "results": []})

        from_name = (_user_smtp_settings(u).get("from_name", "") or "").strip()
        run_async = bool(payload.get("async")) or len(recipients) > 20

        def _do_send(job_id_: Optional[str] = None):
            sent_ = 0
            failed_ = 0
            results_ = []
            total_ = len(recipients)
            for idx, c in enumerate(recipients):
                to_addr = (c.get("email") or "").strip()
                if not to_addr or not EMAIL_RE.match(to_addr):
                    failed_ += 1
                    results_.append({"client_id": c.get("id", ""), "ok": False, "error": "Missing/invalid email"})
                else:
                    ctx = {"name": c.get("name", ""), "company": c.get("company", "")}
                    body = _safe_render(body_t, ctx)
                    try:
                        _unsub_tok = _unsub_token(uname, to_addr)
                        _unsub_base = (PUBLIC_BASE_URL or "").rstrip("/")
                        body = _add_unsub_footer(body, f"{_unsub_base}/unsubscribe/{_unsub_tok}")
                    except Exception:
                        pass
                    ok_send, provider, err = _crm_send_email_to(u, to_addr, subject, body, from_name=from_name)
                    if ok_send:
                        sent_ += 1
                    else:
                        failed_ += 1
                    results_.append({"client_id": c.get("id", ""), "ok": bool(ok_send), "provider": provider, "error": err})
                if job_id_:
                    _BROADCAST_JOBS[job_id_] = {"status": "running", "sent": sent_, "failed": failed_,
                                                 "count": total_, "progress": idx + 1, "results": results_}
            _crm_log_message(uname, {"type": "broadcast_email", "subject": subject, "filter": filt, "sent": sent_, "failed": failed_})
            if sent_ > 0:
                _award_points(uname, "Sent an email broadcast", 30)
                _fire_outbound_webhooks(uname, "broadcast_sent", {"recipient_count": sent_, "subject": subject[:80]})
            if job_id_:
                _notif_push(uname, "Email broadcast complete",
                            f"Sent {sent_}, failed {failed_} of {total_}", "success")
                _BROADCAST_JOBS[job_id_] = {"status": "done", "sent": sent_, "failed": failed_,
                                             "count": total_, "progress": total_, "results": results_}
            return sent_, failed_, results_

        if run_async:
            job_id = uuid.uuid4().hex
            _BROADCAST_JOBS[job_id] = {"status": "running", "sent": 0, "failed": 0,
                                        "count": len(recipients), "progress": 0, "results": []}
            threading.Thread(target=_do_send, args=(job_id,), daemon=True).start()
            return jsonify({"ok": True, "async": True, "job_id": job_id, "count": len(recipients)})

        sent, failed, results = _do_send()
        return jsonify({"ok": True, "count": len(recipients), "sent": sent, "failed": failed, "results": results})

    except Exception as e:
        return jsonify({"ok": False, "error": str(e) or "Broadcast failed"}), 500


