@app.post("/api/crm/log_note")
def api_crm_log_note():
    """Append a timestamped note to a CRM contact matched by email."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"
    payload = request.get_json(silent=True) or {}
    email      = (payload.get("email") or "").strip().lower()
    note_text  = (payload.get("note") or "").strip()
    task_title = (payload.get("task_title") or "").strip()
    if not email or not note_text:
        return jsonify({"ok": False, "error": "Missing email or note"}), 400
    crm = _crm_load(uname)
    clients = crm.get("clients") or {}
    matched_id = None
    for cid, c in clients.items():
        if isinstance(c, dict) and (c.get("email") or "").strip().lower() == email:
            matched_id = cid
            break
    if not matched_id:
        return jsonify({"ok": False, "error": "No CRM contact found with that email"}), 404
    c = clients[matched_id]
    timestamp = now_iso()[:10]
    prefix = f"[{timestamp}] {task_title}: " if task_title else f"[{timestamp}] "
    existing_notes = (c.get("notes") or "").strip()
    c["notes"] = (existing_notes + ("\n" if existing_notes else "") + prefix + note_text).strip()
    crm["clients"][matched_id] = c
    _crm_save(uname, crm)
    return jsonify({"ok": True, "note": prefix + note_text})


@app.errorhandler(Exception)
def _handle_exception(e):
    try:
        # Skip logging 404s and auth errors — they're not real crashes
        code = getattr(e, "code", 500) or 500
        if code not in (404, 401, 403):
            _capture_error(e, context="unhandled_exception")
        try:
            path = request.path or ""
        except Exception:
            path = ""
        if path.startswith("/api/"):
            resp = jsonify({"ok": False, "error": str(e) or "Internal server error"})
            resp.headers["Content-Type"] = "application/json"
            resp.headers["Cache-Control"] = "no-store"
            return resp, code
    except Exception:
        pass
    raise e

@app.errorhandler(404)
def _handle_404(e):
    try:
        if (request.path or "").startswith("/api/"):
            return jsonify({"ok": False, "error": "Endpoint not found"}), 404
    except Exception:
        pass
    # Branded 404 — consistent with _error_404 above
    page = (
        f"<!doctype html><html><head><meta charset='utf-8'/>"
        f"<title>404 — {APP_TITLE}</title>"
        f"<style>{_ERROR_PAGE_CSS}</style></head><body>"
        f"<div class='box'>"
        f"<h1>404</h1><h2>Page not found</h2>"
        f"<p>The page you're looking for doesn't exist or has moved.</p>"
        f"<a href='/'>← Back to {APP_TITLE}</a></div></body></html>"
    )
    return page, 404

@app.errorhandler(500)
def _handle_500(e):
    try:
        if (request.path or "").startswith("/api/"):
            return jsonify({"ok": False, "error": "Internal server error"}), 500
    except Exception:
        pass
    page = (
        f"<!doctype html><html><head><meta charset='utf-8'/>"
        f"<title>500 — {APP_TITLE}</title>"
        f"<style>{_ERROR_PAGE_CSS}</style></head><body>"
        f"<div class='box'>"
        f"<h1>500</h1><h2>Something went wrong</h2>"
        f"<p>An unexpected error occurred. Please try again in a moment.</p>"
        f"<a href='/'>← Back to {APP_TITLE}</a></div></body></html>"
    )
    return page, 500



# =========================
# ADMIN AUDIT TRAIL
# =========================
_ADMIN_AUDIT_LOCK = threading.Lock()

def _admin_audit_path() -> Path:
    try:
        return DATA / "admin_audit.json"
    except Exception:
        return Path("admin_audit.json")

def _admin_audit(admin_username: str, action: str, target: str = "", metadata: Optional[Dict[str, Any]] = None) -> None:
    """Append an admin action to the audit log. Best-effort, never raises."""
    try:
        entry = {
            "ts":       now_iso(),
            "admin":    admin_username or "unknown",
            "action":   action,
            "target":   target or "",
            "meta":     metadata or {},
        }
        try:
            entry["ip"] = (request.headers.get("X-Forwarded-For") or request.remote_addr or "").split(",")[0].strip()
        except Exception:
            pass
        path = _admin_audit_path()
        with _ADMIN_AUDIT_LOCK:
            try:
                log = json.loads(path.read_text(encoding="utf-8")) if path.exists() else []
                if not isinstance(log, list):
                    log = []
            except Exception:
                log = []
            log.append(entry)
            log = log[-2000:]  # keep last 2000 entries
            tmp = path.with_suffix(".tmp")
            tmp.write_text(json.dumps(log, indent=2), encoding="utf-8")
            tmp.replace(path)
    except Exception:
        pass

@app.get("/admin/errors")
def admin_error_log():
    """Admin-only: view the self-hosted error log."""
    u = current_user()
    if not u or not _is_admin_user(u):
        return redirect(url_for("login"))

    try:
        log = json.loads(_error_log_path().read_text(encoding="utf-8")) if _error_log_path().exists() else []
    except Exception:
        log = []

    rows = ""
    for entry in log:
        color = "#fee2e2" if entry.get("type") else "#f8fafc"
        tb = (entry.get("traceback") or "").replace("<", "&lt;").replace(">", "&gt;")
        rows += f"""
        <details style="background:{color};border:1px solid rgba(0,0,0,.08);border-radius:8px;margin-bottom:10px;padding:12px 16px;">
          <summary style="cursor:pointer;font-size:13px;font-weight:600;color:#1e293b;">
            [{entry.get('at','')[:19].replace('T',' ')}]&nbsp;
            <span style="color:#dc2626;">{entry.get('type','?')}</span>&nbsp;—&nbsp;
            {entry.get('method','?')} {entry.get('path','')} &nbsp;
            <span style="color:#64748b;font-weight:400;">{str(entry.get('message',''))[:120]}</span>
          </summary>
          <pre style="margin:10px 0 0;font-size:11px;white-space:pre-wrap;color:#334155;overflow-x:auto;">{tb}</pre>
        </details>"""

    clear_btn = """<form method="post" action="/admin/errors/clear" style="display:inline;">
        <button style="background:#dc2626;color:#fff;border:none;border-radius:6px;padding:8px 16px;cursor:pointer;font-size:13px;">
        Clear all errors</button></form>"""

    html = f"""<!doctype html><html lang="en"><head>
    <meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/>
    <title>Error Log — {APP_TITLE}</title>
    <style>body{{font-family:system-ui,sans-serif;background:#f1f5f9;margin:0;padding:24px;}}
    h1{{font-size:20px;font-weight:700;color:#0f172a;margin:0 0 4px;}}
    .meta{{font-size:13px;color:#64748b;margin:0 0 20px;}}
    a{{color:#6d28d9;font-size:13px;}}</style></head><body>
    <h1>Error Log</h1>
    <p class="meta">{len(log)} error(s) stored (last 200 kept) &nbsp;·&nbsp; {clear_btn} &nbsp;·&nbsp; <a href="/">← Back</a></p>
    {'<p style="color:#64748b;font-size:14px;">No errors recorded yet. 🎉</p>' if not log else rows}
    </body></html>"""
    return html

@app.post("/admin/errors/clear")
def admin_error_log_clear():
    u = current_user()
    if not u or not _is_admin_user(u):
        return redirect(url_for("login"))
    try:
        _error_log_path().write_text("[]", encoding="utf-8")
        uname = (u.get("username") if isinstance(u, dict) else None) or "admin"
        _admin_audit(uname, "clear_error_log")
    except Exception:
        pass
    return redirect(url_for("admin_error_log"))

@app.get("/api/admin/errors")
def api_admin_errors():
    """JSON version of the error log. Tracebacks are stripped for security — use the
    admin UI (/admin/errors) to view full details with proper access control."""
    u = current_user()
    if not u or not _is_admin_user(u):
        return jsonify({"ok": False, "error": "Admin only"}), 403
    try:
        log = json.loads(_error_log_path().read_text(encoding="utf-8")) if _error_log_path().exists() else []
    except Exception:
        log = []
    # Sanitize: remove traceback and internal path details from API response
    safe_log = []
    for entry in log:
        safe_log.append({
            "id":      entry.get("id", ""),
            "at":      entry.get("at", ""),
            "context": entry.get("context", ""),
            "type":    entry.get("type", ""),
            "message": entry.get("message", "")[:200],  # truncate long messages
            "path":    entry.get("path", ""),
            "method":  entry.get("method", ""),
            # traceback intentionally omitted from API response
        })
    return jsonify({"ok": True, "count": len(safe_log), "errors": safe_log})





