@app.get("/api/usage/summary")
def api_usage_summary():
    """Return token usage summary for the current user."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"
    entries = _read_token_usage(uname, limit=5000)
    if not entries:
        return jsonify({"ok": True, "summary": {"total_input": 0, "total_output": 0, "total_calls": 0, "by_model": {}, "by_teammate": {}, "recent": []}})
    total_in  = sum(int(e.get("input_tokens", 0))  for e in entries)
    total_out = sum(int(e.get("output_tokens", 0)) for e in entries)
    by_model: dict = {}
    by_tm: dict = {}
    for e in entries:
        m = e.get("model") or "unknown"
        by_model[m] = by_model.get(m, 0) + int(e.get("total_tokens", 0))
        tm = e.get("teammate") or "unknown"
        by_tm[tm] = by_tm.get(tm, 0) + int(e.get("total_tokens", 0))
    recent = entries[-20:][::-1]
    return jsonify({"ok": True, "summary": {
        "total_input":   total_in,
        "total_output":  total_out,
        "total_tokens":  total_in + total_out,
        "total_calls":   len(entries),
        "by_model":      dict(sorted(by_model.items(), key=lambda x: x[1], reverse=True)),
        "by_teammate":   dict(sorted(by_tm.items(), key=lambda x: x[1], reverse=True)[:10]),
        "recent":        recent,
    }})

_DASHBOARD_CACHE: Dict[str, Any] = {}
_DASHBOARD_CACHE_LOCK = threading.Lock()
_DASHBOARD_CACHE_TTL  = 30  # seconds

def _invalidate_dashboard_cache(username: str) -> None:
    """Clear cached dashboard stats for a user (call after data-mutating operations)."""
    with _DASHBOARD_CACHE_LOCK:
        _DASHBOARD_CACHE.pop(username, None)

@app.get("/api/dashboard")
def api_dashboard():
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = (u.get("username") if isinstance(u, dict) else None) or "anon"
    # Return cached stats if fresh (avoids re-reading 200 task log entries on every poll)
    _now_ts = datetime.utcnow().timestamp()
    with _DASHBOARD_CACHE_LOCK:
        _hit = _DASHBOARD_CACHE.get(uname)
        if _hit and (_now_ts - _hit["ts"]) < _DASHBOARD_CACHE_TTL:
            return jsonify(_hit["payload"])
    stats: Dict[str, Any] = {}

    entries       = read_task_log(limit=200)
    tm_counts: Dict[str, int] = {}
    for e in entries:
        tm = e.get("teammate") or "unknown"
        tm_counts[tm] = tm_counts.get(tm, 0) + 1
    stats["activity"] = {
        "total_actions":  len(entries),
        "error_count":    sum(1 for e in entries if e.get("status") == "error"),
        "top_teammates":  [{"name": t, "count": c}
                           for t, c in sorted(tm_counts.items(), key=lambda x: x[1], reverse=True)[:5]],
        "recent":         entries[-8:][::-1],
    }

    try:
        crm     = _crm_load(uname)
        clients = list((crm.get("clients") or {}).values())
        stages: Dict[str, int] = {}
        stage_values: Dict[str, float] = {}
        total_pipeline_value = 0.0
        week_ago = (datetime.utcnow() - timedelta(days=7)).strftime("%Y-%m-%d")
        leads_this_week = 0
        for c in clients:
            if isinstance(c, dict):
                s = (c.get("pipeline_stage") or "No stage").strip() or "No stage"
                stages[s] = stages.get(s, 0) + 1
                dv = float(c.get("deal_value") or 0)
                stage_values[s] = stage_values.get(s, 0.0) + dv
                total_pipeline_value += dv
                created = (c.get("created_at") or "")[:10]
                if created >= week_ago:
                    leads_this_week += 1
        # emails sent from messages log
        messages = crm.get("messages") or []
        emails_sent = sum(1 for m in messages if isinstance(m, dict) and m.get("ok") and m.get("channel","email")=="email")
        # active enrollments
        enrollments = crm.get("enrollments") or {}
        active_enrollments = sum(1 for e in (enrollments.values() if isinstance(enrollments, dict) else enrollments) if isinstance(e, dict) and (e.get("status") or "active")=="active")
        stats["crm"] = {
            "total_clients": len(clients),
            "stages": stages,
            "stage_values": stage_values,
            "pipeline_value": total_pipeline_value,
            "leads_this_week": leads_this_week,
            "emails_sent": emails_sent,
            "active_enrollments": active_enrollments,
        }
    except Exception:
        stats["crm"] = {"total_clients": 0, "stages": {}, "stage_values": {}, "pipeline_value": 0, "leads_this_week": 0, "emails_sent": 0, "active_enrollments": 0}

    try:
        runs_data = _load_runs(uname)
        all_runs  = list((runs_data.get("runs") or {}).values())
        by_status: Dict[str, int] = {}
        for r in all_runs:
            if isinstance(r, dict):
                s = r.get("status") or "unknown"
                by_status[s] = by_status.get(s, 0) + 1
        stats["runs"] = {"total": len(all_runs), "by_status": by_status}
    except Exception:
        stats["runs"] = {"total": 0, "by_status": {}}

    try:
        scheds = _load_schedules(uname)
        stats["schedules"] = {
            "total": len(scheds),
            "items": [{"teammate": s.get("teammate"), "stack": s.get("stack_name"),
                       "mode": s.get("mode"), "last_run": s.get("last_run")} for s in scheds[:10]],
        }
    except Exception:
        stats["schedules"] = {"total": 0, "items": []}

    try:
        rag_meta = _rag_load_meta(uname)
        docs     = list((rag_meta.get("docs") or {}).values())
        stats["rag"] = {"total_docs": len(docs),
                        "total_chunks": sum(int(d.get("chunks") or 0) for d in docs)}
    except Exception:
        stats["rag"] = {"total_docs": 0, "total_chunks": 0}

    try:
        smem = (_os_load(uname).get("shared_team_memory") or {})
        stats["shared_memory"] = {
            "facts": len(smem.get("facts") or []),
            "decisions": len(smem.get("decisions") or []),
            "open_loops": len(smem.get("open_loops") or []),
            "updated_at": smem.get("updated_at") or "",
        }
    except Exception:
        stats["shared_memory"] = {"facts": 0, "decisions": 0, "open_loops": 0, "updated_at": ""}

    try:
        wh_data = _load_webhooks()
        mine    = [wh for wh in (wh_data.get("webhooks") or {}).values()
                   if isinstance(wh, dict) and wh.get("owner") == uname]
        stats["webhooks"] = {"total": len(mine),
                             "total_triggers": sum(int(w.get("trigger_count") or 0) for w in mine)}
    except Exception:
        stats["webhooks"] = {"total": 0, "total_triggers": 0}

    _payload = {"ok": True, "stats": stats, "generated_at": now_iso()}
    with _DASHBOARD_CACHE_LOCK:
        _DASHBOARD_CACHE[uname] = {"ts": datetime.utcnow().timestamp(), "payload": _payload}
    return jsonify(_payload)


