@app.get("/api/tts/test")
def api_tts_test():
    """End-to-end TTS smoke test. Generates 1 second of audio and confirms the key works."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    user_key  = _decrypt_field(((u.get("settings") or {}).get("openai_key") or "").strip())
    server_key = (OPENAI_API_KEY or "").strip()
    openai_key = user_key or server_key
    source = "user_settings" if user_key else ("env_var" if server_key else "none")
    if not openai_key:
        return jsonify({"ok": False, "error": "No OpenAI key found anywhere.", "source": source})
    try:
        oai = OpenAI(api_key=openai_key)
        resp = oai.audio.speech.create(model="tts-1", voice="alloy", input="Test.")
        return jsonify({"ok": True, "source": source, "bytes": len(resp.content),
                        "key_hint": ("sk-..." + openai_key[-4:]) if len(openai_key) >= 4 else "?"})
    except Exception as exc:
        code, msg = _classify_openai_error(exc)
        return jsonify({"ok": False, "error": msg, "source": source,
                        "key_hint": ("sk-..." + openai_key[-4:]) if len(openai_key) >= 4 else "?"}), code


@app.get("/api/tts/debug")
def api_tts_debug():
    """Debug endpoint: shows exactly what the TTS route sees for this user.
    Safe — never returns the actual key, only metadata."""
    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    settings = u.get("settings") or {}
    openai_key = _decrypt_field((settings.get("openai_key") or "").strip())
    key_len = len(openai_key)
    key_hint = ("sk-..." + openai_key[-4:]) if key_len >= 4 else ("(empty)" if not openai_key else openai_key)
    return jsonify({
        "ok": True,
        "username": u.get("username"),
        "key_present": bool(openai_key),
        "key_len": key_len,
        "key_hint": key_hint,
        "key_starts_with_sk": openai_key.startswith("sk-") if openai_key else False,
        "settings_keys": list(settings.keys()),
    })




@app.post("/api/tts")
def api_tts():
    """Convert text to speech using OpenAI TTS-1.
    Returns raw MP3 bytes so the frontend can play them with an Audio element."""
    from flask import Response

    u = current_user()
    if not u:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401

    payload = request.get_json(force=True) or {}
    text    = (payload.get("text")  or "").strip()[:2000]   # cap at ~30 s
    voice   = (payload.get("voice") or "alloy").strip()
    if voice not in ("alloy", "echo", "fable", "onyx", "nova", "shimmer"):
        voice = "alloy"
    if not text:
        return jsonify({"ok": False, "error": "Missing text"}), 400

    # TTS: prefer the user's own stored key, fall back to the server-level OPENAI_API_KEY env var.
    # This means voice works as long as EITHER the user has entered their key OR the server has one.
    user_key = _decrypt_field(((u.get("settings") or {}).get("openai_key") or "").strip())
    openai_key = user_key or (OPENAI_API_KEY or "").strip()
    username = u.get("username", "unknown")
    key_source = "user_settings" if user_key else ("env_var" if openai_key else "none")
    print(f"[TTS] user={username} key_source={key_source} key_len={len(openai_key)} text_len={len(text)} voice={voice}", flush=True)
    if not openai_key:
        print(f"[TTS] FAIL: no openai_key anywhere for user={username}", flush=True)
        return jsonify({"ok": False, "error": "Voice requires an OpenAI API key. Go to Settings and paste your OpenAI key (sk-...)."}), 400

    openai_key = openai_key.strip()

    try:
        oai  = OpenAI(api_key=openai_key)
        print(f"[TTS] calling openai tts-1 voice={voice} text_preview={text[:60]!r}", flush=True)
        resp = oai.audio.speech.create(model="tts-1", voice=voice, input=text)
        return Response(
            resp.content,
            mimetype="audio/mpeg",
            headers={
                "Cache-Control":        "no-store",
                "Content-Disposition":  "inline; filename=speech.mp3",
            },
        )
    except Exception as exc:
        print(f"[TTS] EXCEPTION: {exc}", flush=True)
        code, msg = _classify_openai_error(exc)
        return jsonify({"ok": False, "error": msg}), code


# ═══════════════════════════════════════════════════════════════════
#  COMMUNITY HUB — Points, Levels, Leaderboard, Idea Board
# ═══════════════════════════════════════════════════════════════════

COMMUNITY_POINTS_FILE = DATA / "community_points.json"
COMMUNITY_IDEAS_FILE  = DATA / "community_ideas.json"

# ── Rank Tiers ─────────────────────────────────────────────────────────────
# Single source of truth. "unlocks" lists feature keys gated to this tier+.
RANK_TIERS: List[Dict[str, Any]] = [
    {
        "tier": 1, "name": "Operator in Training", "emoji": "🌱",
        "min": 0,     "next": 100,
        "unlocks": [],
    },
    {
        "tier": 2, "name": "Field Agent", "emoji": "⚡",
        "min": 100,   "next": 500,
        "unlocks": ["action_stacks"],
    },
    {
        "tier": 3, "name": "Command Ready", "emoji": "🔥",
        "min": 500,   "next": 1500,
        "unlocks": ["action_stacks", "orchestra", "memory_boost"],
    },
    {
        "tier": 4, "name": "Senior Operator", "emoji": "💎",
        "min": 1500,  "next": 5000,
        "unlocks": ["action_stacks", "orchestra", "memory_boost", "deep_dive", "persona_export"],
    },
    {
        "tier": 5, "name": "Elite Operator", "emoji": "🚀",
        "min": 5000,  "next": 15000,
        "unlocks": ["action_stacks", "orchestra", "memory_boost", "deep_dive", "persona_export", "fusion", "compass_pro"],
    },
    {
        "tier": 6, "name": "Legendary", "emoji": "👑",
        "min": 15000, "next": None,
        "unlocks": ["action_stacks", "orchestra", "memory_boost", "deep_dive", "persona_export", "fusion", "compass_pro", "legendary_badge"],
    },
]

def _get_user_rank(points: int) -> Dict[str, Any]:
    """Return the full rank tier dict for a given point total, plus progress info."""
    tier = RANK_TIERS[0]
    for t in reversed(RANK_TIERS):
        if points >= t["min"]:
            tier = t
            break
    nxt = tier["next"]
    if nxt is None:
        progress_pct = 100
        points_to_next = 0
    else:
        span = nxt - tier["min"]
        earned = points - tier["min"]
        progress_pct = min(100, int((earned / span) * 100)) if span > 0 else 100
        points_to_next = max(0, nxt - points)
    return {
        **tier,
        "points":         points,
        "progress_pct":   progress_pct,
        "points_to_next": points_to_next,
    }

# Legacy alias so existing callers don't break
def _community_level(points: int) -> Dict[str, Any]:
    r = _get_user_rank(points)
    return {"name": r["name"], "emoji": r["emoji"], "min": r["min"], "next": r["next"]}

def _user_has_unlock(username: str, feature_key: str) -> bool:
    """Return True if the user's current rank includes the given feature unlock."""
    try:
        data  = _community_load_points()
        total = (data.get(username) or {}).get("total", 0)
        rank  = _get_user_rank(total)
        return feature_key in rank.get("unlocks", [])
    except Exception:
        return False

def _check_rank_up_and_notify(username: str, old_total: int, new_total: int) -> None:
    """Fire a notification if the user just crossed into a new tier."""
    try:
        old_tier = _get_user_rank(old_total)["tier"]
        new_tier = _get_user_rank(new_total)["tier"]
        if new_tier > old_tier:
            new_rank = _get_user_rank(new_total)
            _fire_outbound_webhooks(username, "rank_up", {"tier": new_rank.get("tier"), "name": new_rank.get("name","")})
            _notif_push(
                username,
                title=f"🎉 Rank Up! You are now {new_rank['emoji']} {new_rank['name']}",
                body=f"You've unlocked: {', '.join(new_rank['unlocks']) if new_rank['unlocks'] else 'new prompts'}. Keep going!",
                ntype="success",
                link="/",
            )
    except Exception:
        pass

def _community_week_key() -> str:
    from datetime import datetime
    now = datetime.utcnow()
    return f"{now.year}-W{now.isocalendar()[1]:02d}"

def _community_load_points() -> dict:
    return load_json(COMMUNITY_POINTS_FILE, {})

def _community_save_points(data: dict) -> None:
    save_json(COMMUNITY_POINTS_FILE, data)

def _award_points(username: str, event: str, amount: int) -> int:
    """Award points to a user. Returns new total. Fire-and-forget safe.
    Chat events are capped at 10 per day to prevent leaderboard inflation."""
    try:
        if not username or amount <= 0:
            return 0
        data = _community_load_points()
        week = _community_week_key()
        today = datetime.utcnow().strftime("%Y-%m-%d")
        if username not in data:
            data[username] = {"total": 0, "weeks": {}, "history": [], "daily_chat": {}}
        u = data[username]

        # Diminishing returns: chat events capped at 10 awards per day
        _is_chat_event = "Chat" in event or "chat" in event
        if _is_chat_event:
            daily = u.setdefault("daily_chat", {})
            today_count = daily.get(today, 0)
            if today_count >= 10:
                return u.get("total", 0)  # cap reached — no points for today
            daily[today] = today_count + 1
            # Prune old days (keep last 7)
            u["daily_chat"] = {d: v for d, v in daily.items()
                               if d >= (datetime.utcnow() - timedelta(days=7)).strftime("%Y-%m-%d")}

        old_total = u.get("total", 0)
        u["total"] = old_total + amount
        u.setdefault("weeks", {})[week] = u["weeks"].get(week, 0) + amount
        hist = u.setdefault("history", [])
        hist.insert(0, {"event": event, "amount": amount, "ts": now_iso()})
        u["history"] = hist[:100]
        _community_save_points(data)
        new_total = u["total"]
        # Fire rank-up notification in background so it never blocks the caller
        try:
            threading.Thread(
                target=_check_rank_up_and_notify,
                args=(username, old_total, new_total),
                daemon=True,
            ).start()
        except Exception:
            pass
        return new_total
    except Exception:
        return 0

def _community_get_user_stats(username: str) -> dict:
    data = _community_load_points()
    week = _community_week_key()
    ud = data.get(username, {"total": 0, "weeks": {}, "history": []})
    total  = ud.get("total", 0)
    weekly = ud.get("weeks", {}).get(week, 0)
    rank_info = _get_user_rank(total)
    # leaderboard position (1-based)
    totals = sorted([v.get("total", 0) for v in data.values()], reverse=True)
    lb_rank = totals.index(total) + 1 if total in totals else len(totals) + 1
    return {
        "total": total, "weekly": weekly,
        "level":          {"name": rank_info["name"], "emoji": rank_info["emoji"], "min": rank_info["min"], "next": rank_info["next"]},
        "rank_info":      rank_info,   # full tier data including unlocks + progress
        "rank":           lb_rank,
        "total_users":    len(data),
        "history":        ud.get("history", [])[:15],
    }

def _community_load_ideas() -> list:
    return load_json(COMMUNITY_IDEAS_FILE, [])

def _community_save_ideas(ideas: list) -> None:
    save_json(COMMUNITY_IDEAS_FILE, ideas)

def _community_is_admin(u: dict) -> bool:
    """Account owner (not a team-invited member) can moderate ideas."""
    if not u: return False
    return not u.get("owner")




# =========================
# IN-APP NOTIFICATION SYSTEM
# =========================
# Lightweight per-user notification feed. Stores last 50 notifications.
# Surfaced via GET /api/notifications. Marked read via POST /api/notifications/read.

_NOTIF_MAX = 50
_NOTIF_LOCK = threading.Lock()

def _notif_push(username: str, title: str, body: str = "", ntype: str = "info", link: str = "") -> None:
    """Push a notification to a user's feed. Types: info, success, warning, error."""
    try:
        notif_path = Path(DATA_DIR) / f"notif_{username}.json"
        record = {
            "id":      "n_" + secrets.token_hex(6),
            "ts":      now_iso(),
            "title":   title,
            "body":    body,
            "type":    ntype,
            "link":    link,
            "read":    False
        }
        with _NOTIF_LOCK:
            try:
                notifs = json.loads(notif_path.read_text(encoding="utf-8")) if notif_path.exists() else []
            except Exception:
                notifs = []
            notifs.append(record)
            if len(notifs) > _NOTIF_MAX:
                notifs = notifs[-_NOTIF_MAX:]
            tmp = str(notif_path) + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(notifs, f)
            os.replace(tmp, str(notif_path))
    except Exception:
        pass

@app.get("/api/notifications")
def api_notifications_get():
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = u.get("username", "")
    try:
        notif_path = Path(DATA_DIR) / f"notif_{uname}.json"
        notifs = json.loads(notif_path.read_text(encoding="utf-8")) if notif_path.exists() else []
        unread = sum(1 for n in notifs if not n.get("read"))
        return jsonify({"ok": True, "notifications": list(reversed(notifs[-30:])), "unread": unread})
    except Exception as e:
        _capture_error(e, context="notifications_get")
        return jsonify({"ok": False, "error": str(e)}), 500

@app.post("/api/notifications/read")
def api_notifications_mark_read():
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = u.get("username", "")
    body = request.get_json(silent=True) or {}
    notif_id = body.get("id")  # None = mark all read
    try:
        notif_path = Path(DATA_DIR) / f"notif_{uname}.json"
        with _NOTIF_LOCK:
            notifs = json.loads(notif_path.read_text(encoding="utf-8")) if notif_path.exists() else []
            for n in notifs:
                if notif_id is None or n.get("id") == notif_id:
                    n["read"] = True
            tmp = str(notif_path) + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(notifs, f)
            os.replace(tmp, str(notif_path))
        return jsonify({"ok": True})
    except Exception as e:
        _capture_error(e, context="notifications_mark_read")
        return jsonify({"ok": False, "error": str(e)}), 500

@app.post("/api/notifications")
def api_notifications_push():
    """Frontend-initiated notification push (e.g. after async broadcast)."""
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = u.get("username", "")
    body = request.get_json(silent=True) or {}
    title = (body.get("title") or "").strip()[:120]
    msg   = (body.get("body")  or "").strip()[:240]
    ntype = body.get("type", "info")
    if title:
        _notif_push(uname, title, msg, ntype)
    return jsonify({"ok": True})

@app.delete("/api/notifications")
def api_notifications_clear():
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = u.get("username", "")
    try:
        notif_path = Path(DATA_DIR) / f"notif_{uname}.json"
        if notif_path.exists(): notif_path.unlink()
        return jsonify({"ok": True})
    except Exception as e:
        _capture_error(e, context="notifications_clear")
        return jsonify({"ok": False, "error": str(e)}), 500

# =========================
# USER API KEY SYSTEM
# =========================
# Personal access tokens for integrating Simply Agentic AI with external tools.
# Stored hashed in the user record. Shown once at creation.

def _generate_api_key() -> str:
    import secrets
    return "sa_" + secrets.token_urlsafe(32)

def _hash_api_key(key: str) -> str:
    return hashlib.sha256(key.encode()).hexdigest()

@app.get("/api/user/api-keys")
def api_user_keys_list():
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = u.get("username", "")
    data = load_users()
    user = (data.get("users") or {}).get(uname, {})
    keys = user.get("api_keys") or []
    # Return metadata only — never the raw key
    safe = [{"id": k["id"], "label": k.get("label",""), "created_at": k.get("created_at",""), "last_used": k.get("last_used","")} for k in keys]
    return jsonify({"ok": True, "keys": safe})

@app.post("/api/user/api-keys")
def api_user_keys_create():
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = u.get("username", "")
    body = request.get_json(silent=True) or {}
    label = (body.get("label") or "My API Key").strip()[:64]
    raw_key = _generate_api_key()
    key_id = "key_" + secrets.token_hex(8)
    data = load_users()
    users = data.get("users") or {}
    if uname not in users: return jsonify({"ok": False, "error": "User not found"}), 404
    users[uname].setdefault("api_keys", [])
    users[uname]["api_keys"].append({
        "id": key_id,
        "label": label,
        "hash": _hash_api_key(raw_key),
        "created_at": now_iso(),
        "last_used": ""
    })
    users[uname]["updated_at"] = now_iso()
    data["users"] = users
    save_users(data)
    _audit_log("api_key_created", {"id": key_id, "label": label}, username=uname)
    # Return raw key ONCE — never stored in plaintext
    return jsonify({"ok": True, "key": raw_key, "id": key_id, "label": label,
                    "message": "Save this key now — it will not be shown again."})

@app.delete("/api/user/api-keys/<key_id>")
def api_user_keys_delete(key_id: str):
    u = current_user()
    if not u: return jsonify({"ok": False, "error": "Not authenticated"}), 401
    uname = u.get("username", "")
    data = load_users()
    users = data.get("users") or {}
    if uname not in users: return jsonify({"ok": False, "error": "User not found"}), 404
    keys = users[uname].get("api_keys") or []
    users[uname]["api_keys"] = [k for k in keys if k["id"] != key_id]
    users[uname]["updated_at"] = now_iso()
    data["users"] = users
    save_users(data)
    _audit_log("api_key_deleted", {"id": key_id}, username=uname)
    return jsonify({"ok": True})

def _authenticate_api_key(raw_key: str):
    """Validate a Bearer token API key. Returns user dict or None."""
    if not raw_key or not raw_key.startswith("sa_"):
        return None
    key_hash = _hash_api_key(raw_key)
    data = load_users()
    for uname, user in (data.get("users") or {}).items():
        for k in (user.get("api_keys") or []):
            if k.get("hash") == key_hash:
                # Update last_used timestamp
                try:
                    k["last_used"] = now_iso()
                    save_users(data)
                except Exception:
                    pass
                return user
    return None

