@app.post("/api/extension/ping")
def api_extension_ping():
    """Simple connectivity test from the browser extension."""
    _require_extension_key()
    uname = _get_current_username()
    resp = jsonify({"ok": True, "user": uname, "ts": __import__("time").time()})
    resp.headers["Access-Control-Allow-Origin"] = "*"
    return resp


@app.get("/api/extension/check_contact")
def api_extension_check_contact():
    """Check if a Facebook profile URL already exists as a CRM contact."""
    uname = _ext_authenticate(request)
    if not uname:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    url = (request.args.get("url") or "").strip().rstrip("/").lower()
    if not url:
        return jsonify({"ok": False, "error": "url param required"}), 400
    crm = _crm_load(uname)
    for cid, c in (crm.get("clients") or {}).items():
        stored = (c.get("custom_fields") or {}).get("facebook_url", "").strip().rstrip("/").lower()
        if stored and (stored == url or stored.replace("www.", "") == url.replace("www.", "")):
            return jsonify({"ok": True, "exists": True, "client_id": cid, "name": c.get("name", "")})
    return jsonify({"ok": True, "exists": False})


@app.post("/api/extension/bulk_import")
def api_extension_bulk_import():
    """Batch import multiple Facebook profiles into CRM in one request."""
    uname = _ext_authenticate(request)
    if not uname:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    p = request.get_json(silent=True) or {}
    profiles = p.get("profiles") or []
    if not profiles or not isinstance(profiles, list):
        return jsonify({"ok": False, "error": "profiles array required"}), 400
    crm       = _crm_load(uname)
    plan_key  = _get_user_plan(uname)
    plan_info = PLANS.get(plan_key) or PLANS["starter"]
    max_c     = plan_info.get("crm_contacts")
    imported  = 0
    skipped   = 0
    now       = now_iso()
    # Pre-build URL index for duplicate check
    existing_urls = set()
    for c in (crm.get("clients") or {}).values():
        fu = (c.get("custom_fields") or {}).get("facebook_url", "").strip().rstrip("/").lower()
        if fu:
            existing_urls.add(fu)
            existing_urls.add(fu.replace("www.", ""))
    for prof in profiles[:200]:  # cap at 200 per batch
        if max_c is not None and len(crm.get("clients") or {}) >= max_c:
            skipped += (len(profiles) - imported - skipped)
            break
        name = (prof.get("name") or "").strip()
        if not name:
            skipped += 1
            continue
        profile_url = (prof.get("profile_url") or "").strip().rstrip("/")
        url_key = profile_url.lower()
        url_key_nowww = url_key.replace("www.", "")
        if url_key in existing_urls or url_key_nowww in existing_urls:
            skipped += 1
            continue
        tags = prof.get("tags") or ["Facebook"]
        if isinstance(tags, str):
            tags = [t.strip() for t in tags.split(",") if t.strip()]
        cid = _crm_new_id("c")
        client = {
            "id": cid, "name": name,
            "company": (prof.get("company") or "").strip(),
            "email":   "",
            "phone":   "",
            "tags":    tags,
            "status":  "lead",
            "pipeline_stage": "Lead",
            "notes":   (prof.get("notes") or "").strip(),
            "custom_fields": {
                "facebook_url":  profile_url,
                "import_source": (prof.get("source") or "facebook_extension"),
            },
            "created_at": now, "updated_at": now,
        }
        crm["clients"][cid] = client
        existing_urls.add(url_key)
        existing_urls.add(url_key_nowww)
        imported += 1
    if imported > 0:
        _crm_save(uname, crm)
        _award_points(uname, f"Bulk imported {imported} Facebook contacts", imported * 3)
        _fire_outbound_webhooks(uname, "bulk_import", {"count": imported, "source": "facebook_extension"})
    return jsonify({"ok": True, "imported": imported, "skipped": skipped, "total": len(profiles), "failed": [], "failed_count": 0})


@app.post("/api/extension/log_action")
def api_extension_log_action():
    """Log a social action (like, follow, friend_request) to the CRM contact timeline."""
    uname = _ext_authenticate(request)
    if not uname:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    p = request.get_json(silent=True) or {}
    action      = (p.get("action") or "action").strip()
    profile_url = (p.get("profile_url") or "").strip().rstrip("/")
    name        = (p.get("name") or "").strip()
    detail      = (p.get("detail") or "").strip()
    if not profile_url and not name:
        return jsonify({"ok": False, "error": "profile_url or name required"}), 400
    # Find matching contact and append to notes/timeline
    crm = _crm_load(uname)
    matched_cid = None
    url_lower = profile_url.lower()
    for cid, c in (crm.get("clients") or {}).items():
        fu = (c.get("custom_fields") or {}).get("facebook_url", "").strip().rstrip("/").lower()
        if fu and (fu == url_lower or fu.replace("www.", "") == url_lower.replace("www.", "")):
            matched_cid = cid
            break
    log_entry = f"[{now_iso()[:10]}] Extension: {action}" + (f" — {detail}" if detail else "")
    if matched_cid:
        c = crm["clients"][matched_cid]
        existing_notes = (c.get("notes") or "").strip()
        c["notes"] = (existing_notes + "\n" + log_entry).strip()
        c["updated_at"] = now_iso()
        crm["clients"][matched_cid] = c
        _crm_save(uname, crm)
    # Always log to task log for activity feed
    append_task_log(action, {"name": name, "profile_url": profile_url, "detail": detail, "matched_contact": matched_cid}, teammate="Extension")
    return jsonify({"ok": True, "logged": True, "matched_contact": matched_cid})


@app.post("/api/extension/tag_contact")
def api_extension_tag_contact():
    """Add or remove tags on a CRM contact by Facebook profile URL."""
    uname = _ext_authenticate(request)
    if not uname:
        return jsonify({"ok": False, "error": "Not authenticated"}), 401
    p = request.get_json(silent=True) or {}
    profile_url = (p.get("profile_url") or "").strip().rstrip("/")
    name        = (p.get("name") or "").strip()
    add_tags    = [t.strip() for t in (p.get("add_tags") or []) if t.strip()]
    remove_tags = [t.strip() for t in (p.get("remove_tags") or []) if t.strip()]
    if not profile_url and not name:
        return jsonify({"ok": False, "error": "profile_url or name required"}), 400
    crm = _crm_load(uname)
    url_lower = profile_url.lower()
    matched_cid = None
    for cid, c in (crm.get("clients") or {}).items():
        fu = (c.get("custom_fields") or {}).get("facebook_url", "").strip().rstrip("/").lower()
        if fu and (fu == url_lower or fu.replace("www.", "") == url_lower.replace("www.", "")):
            matched_cid = cid
            break
    # If no contact found by URL but we have a name, try to auto-import
    if not matched_cid and name and profile_url:
        plan_key  = _get_user_plan(uname)
        plan_info = PLANS.get(plan_key) or PLANS["starter"]
        max_c     = plan_info.get("crm_contacts")
        if max_c is None or len(crm.get("clients") or {}) < max_c:
            cid = _crm_new_id("c")
            now = now_iso()
            crm["clients"][cid] = {
                "id": cid, "name": name, "company": "", "email": "", "phone": "",
                "tags": list(add_tags), "status": "lead", "pipeline_stage": "Lead",
                "notes": "", "custom_fields": {"facebook_url": profile_url, "import_source": "extension_tag"},
                "created_at": now, "updated_at": now,
            }
            _crm_save(uname, crm)
            return jsonify({"ok": True, "matched": False, "auto_created": True, "client_id": cid})
        return jsonify({"ok": True, "matched": False, "auto_created": False})
    if matched_cid:
        c = crm["clients"][matched_cid]
        existing = c.get("tags") or []
        if not isinstance(existing, list): existing = []
        new_tags = [t for t in existing if t not in remove_tags]
        for t in add_tags:
            if t not in new_tags: new_tags.append(t)
        c["tags"] = new_tags
        c["updated_at"] = now_iso()
        crm["clients"][matched_cid] = c
        _crm_save(uname, crm)
        return jsonify({"ok": True, "matched": True, "client_id": matched_cid, "tags": new_tags})
    return jsonify({"ok": True, "matched": False, "auto_created": False})


